var deserialize = require('../tree-deserialiser');

var expected = {
    decoded: {
        branches: [0, 2],
        files: 2,
        hash: '0b0ca69d74be872c914b06e8bdee677917e8e9f2',
        name: 'mendel',
        version: 2,
    },
    error: null,
};
var realHash = 'bWVuZGVsAgAC_wIACwymnXS-hyyRSwbove5neRfo6fI';
var result = deserialize(realHash);
